/**
 * Scheme retrieval and matching. Scheme facts come only from the curated catalog
 * (src/data/schemeCatalog.ts) and form schemas — never generated by the model.
 */
import { Type } from '@google/genai';
import { FORM_SCHEMAS, FORM_SCHEMA_MAP } from '../../src/data/autofillSchema';
import { SCHEME_CATALOG, estimateEligibility, rankSchemesForProfile } from '../../src/data/schemeCatalog';
import { DOCUMENT_SERVICES } from '../../src/data/documentServices';
import { LOAN_PRODUCTS, LOAN_WORDS, loanDetails } from '../../src/data/loanCatalog';

/** Schemes, official document services and loans share one lookup. */
const ALL_ENTRIES = [...SCHEME_CATALOG, ...DOCUMENT_SERVICES, ...LOAN_PRODUCTS];
const findEntry = (id: string) => ALL_ENTRIES.find((s) => s.id === id);
import type { BeneficiaryProfile } from '../../src/types';
import type { Generate } from './ocr';
import type { ProfileState } from './types';
import { ageFromDob } from './validate';

const APPLY_WORDS =
  /\b(apply|application|applying|form|register|registration|enrol|enroll|fill)\b|आवेदन|फॉर्म|फ़ॉर्म|अर्ज़ी|अर्जी|पंजीकरण|अर्ज|விண்ணப்ப|படிவம்|దరఖాస్తు|ఫారం|ಅರ್ಜಿ|ನೋಂದಣಿ|അപേക്ഷ|ഫോം|আবেদন|અરજી|ਅਰਜ਼ੀ|ଆବେଦନ|درخواست/i;

export function schemeInfo(schemeId: string) {
  const schema = FORM_SCHEMA_MAP[schemeId];
  const catalog = findEntry(schemeId);
  if (!schema || !catalog) return null;
  const docService = (catalog as any).kind === 'document' ? (catalog as any) : null;
  return {
    schemeId,
    kind: schema.kind || 'scheme',
    category: docService?.category as string | undefined,
    officialForm: schema.officialForm || docService?.officialForm,
    online: docService?.online as string | undefined,
    name: catalog.name,
    ministry: catalog.ministry,
    summary: catalog.summary,
    keySupport: catalog.keySupport,
    eligibilitySummary: catalog.eligibilitySummary,
    documents: catalog.documents,
    steps: catalog.steps,
    officialUrl: catalog.officialUrl,
    officialLabel: catalog.officialLabel,
    formTitle: schema.formTitle,
    basis: schema.basis,
    submission: schema.submission,
    requiredDocs: schema.requiredDocs,
    optionalDocs: schema.optionalDocs,
    /** Amounts, rates and lenders, for loans and loan schemes. */
    loan: loanDetails(schemeId),
  };
}

export const listSchemes = () => FORM_SCHEMAS.map((s) => schemeInfo(s.schemeId)!).filter(Boolean);

/**
 * Fast, free intent check used on every chat message: does the person want to apply,
 * and is a specific supported scheme named?
 */
/** Request verbs for documents ("I need a PAN card", "आधार में पता बदलना है"). */
const DOC_ACTION_WORDS =
  /\b(get|make|need|want|new|renew|update|correct|correction|change|issue|lost|duplicate|how|chahiye|chahie|banwana|banwani|banana|banani|convert)\b|बनवा|बनाना|चाहिए|अपडेट|बदल|सुधार|खो|வேண்டும்|மாற்ற|எப்படி|కావాలి|మార్చ|ఎలా|ಬೇಕು|ಬದಲ|ಹೇಗೆ|വേണം|മാറ്റ|എങ്ങനെ/i;

export function detectIntentLocal(text: string): { wantsToApply: boolean; schemeId: string | null; wantsLoan: boolean } {
  const t = (text || '').toLowerCase();
  let best: string | null = null;
  let bestLen = 0;
  for (const s of FORM_SCHEMAS) {
    for (const k of s.keywords) {
      const kw = k.toLowerCase();
      // Latin keywords must match whole words ("dl" must not match "handle"); Indic ones match as substrings
      const hit = /^[a-z0-9 .\-]+$/.test(kw) ? new RegExp(`(^|[^a-z0-9])${kw.replace(/[.\-]/g, '\\$&')}($|[^a-z0-9])`).test(t) : t.includes(kw);
      if (hit && k.length > bestLen) {
        best = s.schemeId;
        bestLen = k.length;
      }
    }
  }
  const isDocument = best ? FORM_SCHEMA_MAP[best]?.kind === 'document' : false;
  // "I need a loan", "मुझे लोन चाहिए": asking for a loan is asking to apply for one
  const wantsLoan = LOAN_WORDS.test(t);
  const wantsToApply = APPLY_WORDS.test(t) || ((isDocument || wantsLoan) && DOC_ACTION_WORDS.test(t));
  return { wantsToApply, schemeId: best, wantsLoan };
}

/**
 * AI-powered search for what someone needs. Short, explicit requests ("PAN card") are answered
 * from keywords; anything descriptive goes to Gemini, which can also suggest related items
 * (e.g. an income certificate AND the scholarship it is needed for).
 */
export async function detectIntent(generate: Generate, text: string) {
  const local = detectIntentLocal(text);
  const words = text.trim().split(/\s+/).filter(Boolean).length;
  if (local.schemeId && words <= 6) return { ...local, related: [] as string[], matchedBy: 'keywords' as const, reason: '' };
  if (!text.trim()) return { ...local, related: [] as string[], matchedBy: 'none' as const, reason: '' };
  try {
    const options = FORM_SCHEMAS.map((s) => `${s.schemeId}: ${findEntry(s.schemeId)?.name} — ${findEntry(s.schemeId)?.summary}`).join('\n');
    const ids = FORM_SCHEMAS.map((s) => s.schemeId);
    const response = await generate(
      {
        contents: `A citizen in India said (any language): "${text.slice(0, 600)}"
From the list below, choose the ONE government scheme, loan, or official document / certificate service that best matches what they need to apply for now, and up to 2 related items they will probably also need (for example, a scholarship usually also needs an income certificate and a caste certificate; a bank loan need may also fit a cheaper government loan scheme). Use "none" if nothing fits.${local.schemeId ? `\nA keyword match suggested: ${local.schemeId} — use it only if it truly fits.` : ''}
${options}`,
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              schemeId: { type: Type.STRING, enum: [...ids, 'none'] },
              related: { type: Type.ARRAY, items: { type: Type.STRING, enum: ids } },
              wantsToApply: { type: Type.BOOLEAN },
              reason: { type: Type.STRING },
            },
            required: ['schemeId', 'related', 'wantsToApply', 'reason'],
          },
          temperature: 0,
          thinkingConfig: { thinkingBudget: 0 },
        },
      },
      undefined,
      { retryBusy: false, timeoutMs: 12000 }
    );
    const parsed = JSON.parse(response.text || '{}');
    const schemeId = FORM_SCHEMA_MAP[parsed.schemeId] ? parsed.schemeId : null;
    const related = (Array.isArray(parsed.related) ? parsed.related : []).filter((r: string) => FORM_SCHEMA_MAP[r] && r !== schemeId).slice(0, 2);
    return { wantsToApply: local.wantsToApply || Boolean(parsed.wantsToApply), wantsLoan: local.wantsLoan || FORM_SCHEMA_MAP[schemeId || '']?.kind === 'loan', schemeId, related, matchedBy: 'ai' as const, reason: String(parsed.reason || '').slice(0, 300) };
  } catch {
    // AI unavailable: fall back to the keyword result
    return { ...local, related: [] as string[], matchedBy: local.schemeId ? ('keywords' as const) : ('none' as const), reason: '' };
  }
}

/** Convert the stored profile to the shape the existing eligibility rules expect. */
export function toBeneficiaryProfile(profile: ProfileState): BeneficiaryProfile {
  const v = (k: string) => (profile.fields as any)[k]?.value || '';
  const dob = v('dateOfBirth');
  const age = dob ? ageFromDob(dob) : null;
  const cat = v('socialCategory');
  return {
    name: v('fullName'),
    age: age ?? '',
    gender: (['Male', 'Female', 'Transgender'].includes(v('gender')) ? v('gender') : 'Prefer not to say') as any,
    state: v('state'),
    district: v('district'),
    education: v('education'),
    currentOccupation: v('occupation'),
    traditionalTrade: v('occupation'),
    existingSkills: v('existingSkills'),
    mobilityConstraint: '',
    workPreference: 'Any',
    householdIncome: v('annualFamilyIncome'),
    annualFamilyIncome: v('annualFamilyIncome'),
    hasSmartphone: true,
    disabilityStatus: 'None',
    socialCategory: cat === 'SC' ? 'Scheduled Caste (SC)' : cat,
  };
}

/** Recommendations for people who do not know which scheme fits. Preliminary only. */
export function recommend(profile: ProfileState, limit = 4) {
  const bp = toBeneficiaryProfile(profile);
  return rankSchemesForProfile(bp, [], limit)
    .filter((x) => FORM_SCHEMA_MAP[x.s.id])
    .map((x) => ({ ...schemeInfo(x.s.id)!, eligibility: x.e }));
}

export function eligibilityFor(schemeId: string, profile: ProfileState) {
  const catalog = findEntry(schemeId);
  return catalog ? estimateEligibility(catalog, toBeneficiaryProfile(profile)) : null;
}
